    title:
      "Establecer criterios de gestión, recepción y verificación de pedidos",
    isMandatory: true,
    isEssential: false,
    description:
      "El personal conoce el horario de recepción de mercancías y se lo comunica a los proveedores (vía carta, correo electrónico, panel informativo, etc.), intentando que el horario definido no moleste al cliente.\nExiste un documento donde se especifica cómo recibir los materiales solicitados mediante pedido formalizado; se establece la realización de comprobaciones de cantidad y de requisitos específicos solicitados, así como las condiciones para la aceptación o rechazo de los pedidos, tanto de productos perecederos como no perecederos.\nLos pedidos rechazados son separados físicamente de los aceptados, identificándolos de manera clara para evitar su uso.\nEn el caso de productos alimenticios perecederos se comprueba:\n• La temperatura a la que han sido transportados.\n• El registro sanitario del proveedor.\n• La marca de salubridad según el producto.\n• Fecha de caducidad o fecha de consumo preferente.\n•Control visual de las características organolépticas del producto (color, olor característico, textura, firmeza, integridad de los envases, etc.).\n• El correcto etiquetado (ingredientes, lote, fecha de caducidad, alérgenos, etc.).\nNo aplica - Organizaciones sin recepción de mercancías.",
