    title:
      "Establecer un mecanismo para captar, priorizar y aprovechar ideas de mejora e innovación",
    isMandatory: false,
    isEssential: false,
    description:
      "El servicio turístico tiene documentado un sistema de generación y recogida de ideas (buzón de ideas, sesiones de lluvias de ideas, reuniones creativas…) donde recoge y aprovecha las ideas y percepciones de los empleados para mejorar y crecer. Se consideran tanto aspectos físicos como digitales y se fomenta la participación de las personas trabajadoras.\nSe priorizan aquellas ideas alineadas con la estrategia y criterios para la innovación definidos y atendiendo a su viabilidad técnica y rentabilidad esperada. Se valoran también otros parámetros, tales como calidad, precio, recursos y tiempo de lanzamiento al mercado o implantación en la organización.\nEl servicio turístico realiza un registro para la clasificación, valorización, priorización y seguimiento de las ideas.",
