    description:
      "El servicio turístico vela por el bienestar, motivación y rendimiento del personal de su plantilla estableciendo medidas para favorecer el equilibrio entre la vida laboral y personal de las personas trabajadoras. Las medidas establecidas pueden incluir, entre otros aspectos:\n• Horarios flexibles de entrada o salida (cuando el puesto lo permite) o adaptados (para quienes tienen hijos o familiares a cargo).\n• Gestión equitativa de turnos, especialmente en temporadas altas, respetando los tiempos de descanso legal y promoviendo la rotación justa.\n• Permisos breves o excepcionales por razones personales, familiares o de salud, con base en criterios claros y transparentes.\n• Promoción de jornadas laborales sostenibles, evitando la sobrecarga de trabajo y asegurando pausas durante las jornadas intensivas.\n• Atención a situaciones especiales, como maternidad, paternidad, cuidados familiares o estudios, mediante acuerdos internos cuando sea viable.\n• Teletrabajo, cuando el puesto lo permite.",
