    description:
      "El servicio turístico implementa actuaciones orientadas al desarrollo local, teniendo como principales objetivos sensibilizar y beneficiar a la comunidad residente del impacto del turismo. En ese sentido, lleva a cabo actuaciones que fomentan la contratación local, la formación y capacitación y labores de inclusión, así como la sensibilización a la población local en materia de inclusión social.\nA modo de ejemplo, se pueden tener en consideración las siguientes propuestas:\n• Formación e inclusión social: formación en el desarrollo de habilidades y competencias encaminadas a la futura contratación en el servicio turístico.\n• Preferencia en la contratación: establecer políticas que prioricen la contratación de residentes locales en el servicio turístico.\n• Promoción de productos locales: fomentar la venta de productos artesanales locales y alimentos de la región en el servicio turístico.\n• Contratación de empresas sociales y de comercio justo como proveedores preferentes.\n• Participación en decisiones: involucrar a la comunidad en la planificación y desarrollo de proyectos del servicio turístico, de tal forma que sus necesidades y preferencias sean considerados.\n• Cuidado del patrimonio cultural: implementar iniciativas en el servicio turístico, que promuevan la protección de la cultura local, involucrando a los residentes en su preservación.",
