    isMandatory: false,
    isEssential: false,
    description:
      "El servicio turístico debe concienciar y sensibilizar a los turistas y visitantes sobre:\n• El valor y la singularidad de los recursos naturales del destino.\n• La importancia de preservar los recursos naturales del destino, las normas y los accesos diseñados para su preservación y conservación, evitando así impactos negativos que comprometan su supervivencia.\n• Buenas prácticas del turista para la reducción del impacto ambiental de la visita:\no Cuidando los recursos de la naturaleza, especialmente los bosques y los humedales y lugares de especial protección.\no Reduciendo el consumo de agua, energía y envases y gestionando los residuos de forma responsable sin dejar basura, utilizando los contenedores de separación selectiva.\no No introduciendo en el destino especies invasoras, ni comprando flora y fauna protegida, ni productos derivados de dichas especies.\nNota: Esta buena práctica se puede trabajar de manera conjunta con las buenas prácticas indicadas en el apartado BBPP Relacionadas.",
