    isMandatory: false,
    isEssential: false,
    description:
      "El servicio turístico incorpora recursos, procedimientos y condiciones que permiten ofrecer una experiencia adecuada a los clientes que viajan con animales de compañía.\nEsto incluye disponer de información clara sobre las normas de admisión, habilitar espacios o elementos específicos cuando sea posible y garantizar una atención coherente con las necesidades tanto del cliente como del animal. La práctica busca facilitar una estancia cómoda, segura y organizada, integrando este perfil de visitante sin generar barreras ni complicaciones operativas.\nNo aplica – Servicios turísticos que no permitan animales de compañía.",
