    isMandatory: true,
    isEssential: false,
    description:
      "Se considera que una cocina está correctamente limpia cuando:\n• La campana no tiene restos de grasa.\n• Las papeleras y cubos de basura no presentan restos de suciedad.\n• Los suelos y paredes se encuentran sin restos de grasa y/o suciedad.\n• La maquinaria empleada en el proceso productivo no presenta restos de suciedad.\n• Los elementos de iluminación no contienen grasa ni restos de suciedad.\n• El espacio específico destinado a limpieza de utensilios, vajilla y cubertería se encuentra limpio y en perfecto estado de orden.",
