      "Disponer de personal formado en atención y comunicación accesible, inclusiva y no discriminatoria",
    isMandatory: true,
    isEssential: false,
    description:
      "El personal del servicio turístico cuenta con formación en atención y comunicación que garantiza la interacción eficaz, segura, comprensible y respetuosa con todas las personas. La formación, inicial y continua, se actualiza conforme a la normativa y a las buenas prácticas en accesibilidad universal, trato inclusivo y eliminación de barreras comunicativas.\nEl equipo domina técnicas de comunicación inclusiva, no sexista y clara, empleando lenguaje sencillo, frases breves y una estructura ordenada que facilite la comprensión. Está capacitado para ofrecer información en distintos formatos accesibles (oral, escrita, lectura fácil, pictogramas, braille, soporte sonoro o visual) y para adaptarse a las necesidades de cada persona.\nAdemás, el personal conoce y utiliza correctamente los recursos de apoyo disponibles, como bucles magnéticos, señalética accesible, aplicaciones de asistencia o dispositivos tecnológicos que facilitan la comunicación inclusiva.\nNota: Esta buena práctica se puede trabajar de manera conjunta con las buenas prácticas indicadas en el apartado BBPP Relacionadas.",
