    axis: "SOCIAL",
    moduleCode: "138",
    moduleName: "Facturación y pagos adaptados",
    title: "Ofrecer sistemas de autopago presencial accesibles",
    isMandatory: false,
    isEssential: false,
    description:
      "Los sistemas de autopago del servicio turístico están diseñados para ser operables por todas las personas. Las pantallas permiten el ajuste del contraste, tamaño de fuente y navegación por teclado o pantalla táctil.\nLos botones son grandes, con texto claro y pictogramas (inclusivos y no sexistas), y se garantiza compatibilidad con lectores de pantalla y bucles magnéticos. Se ofrece asistencia sonora, subtítulos, instrucciones en lectura fácil y vídeos explicativos con lengua de signos. La altura del terminal permite uso desde silla de ruedas, y se garantiza espacio libre frontal para aproximación.\nSe informa sobre la accesibilidad del sistema mediante cartelería clara y visible (evitando estereotipos de género).\nEn caso de necesitar asistencia, se garantizará personal del servicio turístico o formas de contacto con personal disponible para la asistencia en el proceso de pago.\nNota: Esta buena práctica se puede trabajar de manera conjunta con las buenas prácticas indicadas en el apartado BBPP Relacionadas",
