    axis: "SOCIAL",
    moduleCode: "138",
    moduleName: "Facturación y pagos adaptados",
    title: "Ofrecer un sistema de pago online accesible",
    isMandatory: false,
    isEssential: false,
    description:
      "Las plataformas de pago online de las que dispone el servicio turístico cumplen con las Pautas de Accesibilidad para el Contenido Web, garantizando su uso por parte de todas las personas. Los formularios son simples, con instrucciones claras en lenguaje sencillo, campos etiquetados correctamente y navegación compatible con teclado, ratón o pantalla táctil. Se permite ajustar el contraste, tamaño de letra y colores durante todo el proceso de pago. Los botones y enlaces tienen dimensiones adecuadas para facilitar la selección.\nLa confirmación del pago se presenta con avisos visuales y sonoros, y se ofrecen sistemas de autenticación accesibles como verificación biométrica, códigos por SMS compatibles con lectores de pantalla, y alternativas sin CAPTCHA visual.\nSe incluyen vídeos explicativos con subtítulos, lengua de signos y audiodescripción sobre cómo realizar el pago. El soporte técnico está disponible por canales accesibles, y se recoge retroalimentación para mejorar la experiencia de usuario.\nNota: Esta buena práctica se puede trabajar de manera conjunta con las buenas prácticas indicadas en el apartado BBPP Relacionadas",
    requiresDocs: false,
