    axis: "SOCIAL",
    moduleCode: "141",
    moduleName: "Itinerarios peatonales accesibles",
    title:
      "Garantizar la movilidad accesible dentro de los itinerarios peatonales",
    isMandatory: true,
    isEssential: false,
    description:
      "Los itinerarios peatonales se diseñan y mantienen para asegurar una movilidad cómoda, continua y segura para todas las personas, favoreciendo el desplazamiento autónomo y la convivencia entre distintos tipos de usuarios.\nLas rutas peatonales cuentan con anchura suficiente, pendientes suaves y superficies estables, firmes y antideslizantes, que facilitan el paso de sillas de ruedas, carritos infantiles y ayudas técnicas. Se eliminan desniveles, escalones y obstáculos que puedan dificultar el tránsito o comprometer la seguridad.\nSe incorporan elementos de orientación y guiado accesibles, como pavimentos táctiles, bandas de contraste, señalización en braille, lectura fácil y pictogramas normalizados, así como avisos sonoros o luminosos en puntos de cruce o zonas de riesgo.\nEl mobiliario urbano, la vegetación y los elementos de señalización se ubican fuera de las franjas de paso y con alturas y distancias adecuadas, evitando interferencias o riesgos de impacto.",
    requiresDocs: false,
