    title: "Disponer de espacios y zonas de descanso accesibles",
    isMandatory: false,
    isEssential: false,
    description:
      "Los espacios de descanso son accesibles y confortables, diseñados para responder a las necesidades de todas las personas, favoreciendo la movilidad segura y el uso continuado del espacio público.\nLas zonas de descanso se distribuyen de forma regular y estratégica a lo largo del itinerario peatonal, especialmente en áreas con pendiente, exposición solar o elevada distancia entre puntos de interés. Estos espacios cuentan con mobiliario accesible como fuentes, bancos, mesas y apoyos isquiáticos.\nEl entorno inmediato dispone de espacio libre de obstáculos para maniobras con silla de ruedas, carritos o ayudas técnicas, y se garantiza la accesibilidad sensorial mediante pavimentos contrastados, señalización táctil y visual clara.\nSiempre que sea posible, se incorporan zonas de sombra, protección frente a la lluvia y papeleras accesibles, contribuyendo al confort térmico y a la sostenibilidad del entorno.",
