    isMandatory: false,
    isEssential: false,
    description:
      "La señalética ubicada en el interior y exterior de las instalaciones del servicio turístico garantiza la orientación, seguridad y autonomía de S todas las personas.\nLas señales se ubican a doble altura, accesibles desde silla de ruedas y desde posición de pie, y se distribuyen en puntos clave tanto del interior como del exterior de las instalaciones: entradas, salidas, aseos, ascensores, rampas, zonas de descanso y servicios.\nSe emplean pictogramas normalizados, braille, lectura fácil, alto contraste cromático, iluminación adecuada y relieve táctil.\nToda la señalización debe ser inclusiva, no sexista y debe evitar los estereotipos de género.\nSe incorpora señalización podotáctil en suelos para guiar a personas con discapacidad visual, y se complementa con sistemas sonoros en accesos principales. La información se presenta en lenguaje claro, estructurado y sin tecnicismos, y se actualiza conforme a cambios en la distribución o servicios.",
