      "En el caso de que el servicio turístico disponga de diversos equipamientos y sistemas accesibles a disposición del cliente deberá contar con personal formado en su manejo, garantizando su correcta utilización y la asistencia segura a todas las personas. Esta formación abarca el conocimiento técnico y práctico de distintos equipamientos y dispositivos, como cocinas adaptadas, plataformas elevadoras, sistemas de alarma accesibles, y otros sistemas diseñados bajo criterios de accesibilidad universal.\nEl equipo está preparado para explicar el funcionamiento de cada sistema de forma inclusiva, no sexista y clara, utilizando lenguaje sencillo, demostraciones prácticas y apoyos visuales o táctiles cuando sea necesario. Además, sabe ofrecer asistencia personalizada en el uso de estos equipamientos (como la ayuda para activar un mecanismo o acceder a un sistema digital), siempre respetando la autonomía y el ritmo de cada persona usuaria.\nNota: Esta buena práctica se puede trabajar de manera conjunta con las buenas prácticas indicadas en el apartado BBPP Relacionadas.",
