    isMandatory: true,
    isEssential: false,
    description:
      "Se habilitan plazas de aparcamiento reservadas para personas con movilidad reducida (PMR).\nLas dimensiones de las plazas permiten el estacionamiento de vehículos adaptados y la transferencia lateral desde silla de ruedas.\nLa señalización horizontal incluye pictogramas de accesibilidad (inclusivos, no sexistas y evitando los estereotipos de género) pintados en el pavimento con alto contraste cromático, y la señalización vertical se presenta en placas visibles a altura adecuada, indicando el uso exclusivo. El mantenimiento incluye revisión periódica del estado del pavimento, señalización y accesibilidad del entorno inmediato.\nLa ubicación de las plazas se indica en planos físicos y digitales accesibles, y se supervisa su uso mediante acreditación oficial.\nSe garantiza la conexión directa con rutas accesibles, hacia entradas, servicios y zonas de atención al público.",
