    isMandatory: false,
    isEssential: false,
    description:
      "Las salas o auditorios donde se realizan eventos y espectáculos deben garantizar condiciones estables de accesibilidad. Para ello, cuentan con iluminación uniforme, sin sombras ni parpadeos, y con temperatura de color neutra o cálida que facilite la lectura labial, la visibilidad de la lengua de signos y la correcta percepción de materiales visuales.\nLa acústica se optimiza mediante paneles fonoabsorbentes, aislamiento frente a ruidos externos y control del ruido ambiental. Se eliminan ecos y se mejora la claridad del sonido, asegurando compatibilidad con bucles magnéticos, audífonos e implantes cocleares. La presencia de bucle magnético se señala con pictogramas normalizados.\nLos equipos de iluminación y sonido se revisan periódicamente para garantizar un funcionamiento adecuado y ofrecer una experiencia escénica segura, confortable y accesible para todas las personas usuarias.",
