    isEssential: false,
    description:
      "Se proporcionan cartas accesibles en formatos físicos y/o digitales.\nLas versiones impresas incluyen braille, macrotexto, pictogramas y papel de alto contraste.\nLas digitales están disponibles en la web y mediante códigos QR, compatibles con lectores de pantalla, diseño responsive y subtítulos.\nLa organización de la carta es clara, con secciones diferenciadas y pictogramas para alérgenos, opciones vegetarianas, veganas o sin gluten. La información sobre los platos incluye descripciones textuales, ingredientes y restricciones alimentaria.\nTodos los formatos se actualizan simultáneamente, y se garantiza coherencia en precios e información. El personal está preparado para asistir en la lectura de la carta y se informa visiblemente en el local y en la web sobre la disponibilidad de menús accesibles.\nNota: Esta buena práctica se puede trabajar de manera conjunta con las buenas prácticas indicadas en el apartado BBPP Relacionadas.",
