    isEssential: false,
    description:
      "Los restaurantes disponen de mobiliario accesible y adaptado que garantiza la comodidad, seguridad y autonomía de todas las personas.\nLas mesas cuentan con espacio libre inferior que permite la aproximación frontal desde una silla de ruedas, mientras que las sillas son estables, con respaldo y reposabrazos, y se sitúan a una altura ergonómica que facilita la incorporación y el apoyo. Se incorporan sillas infantiles, tronas y elevadores seguros, así como zonas reservadas para carritos o ayudas técnicas, favoreciendo la convivencia familiar y la accesibilidad.\nLa distribución del mobiliario garantiza amplios espacios de paso y maniobra, sin obstáculos, y los materiales empleados son resistentes, antideslizantes y de fácil limpieza. Además, la iluminación homogénea y el contraste cromático entre mobiliario y suelo facilitan la orientación visual.",
