    isMandatory: false,
    isEssential: false,
    description:
      "El servicio turístico analiza su huella de carbono en su alcance 1(*) y 2(**); con el fin de evaluar las emisiones de gases de efecto invernadero (GEI) que genera directa e indirectamente, según la metodología del Protocolo de Gases de Efecto Invernadero (GHG Protocol) o ISO 14064-1.\n(*) Alcance 1: emisiones controladas por el servicio turístico, derivadas de la combustión de combustibles en instalaciones fijas, consumo de combustibles en vehículos y maquinaria, y fugas de gases fluorados de los equipos de climatización y/o refrigeración calefacción.\n(**) Alcance 2: emisiones ligadas a la energía consumida, como electricidad comprada.\nNo aplica – Servicios turísticos que no generen emisiones de carbono.",
