    description:
      "El servicio turístico aplica medidas de tecnologías modernas, de iluminación eficiente y gestión inteligente de la luz para reducir el consumo energético. Estas medidas pueden ser:\n• Instalación de sensores de movimiento en pasillos, baños comunes o almacenes; que activan la luz solo cuando hay ocupación.\n• Regulación automática de intensidad, que ajusta el nivel de luz según la hora del día, el nivel de luz natural o necesidad de uso.\n• Uso de temporizadores o sensores crepusculares para iluminación exterior.\n• Zonificación lumínica, que procede al encendido selectivo de áreas según uso, evitando iluminación innecesaria de zonas vacías.\n• Favorecer el paso de la luz natural a través de lucernarios, claraboyas, ventas estratégicas, etc.",
