    isMandatory: true,
    isEssential: false,
    description:
      "El servicio turístico facilita a los clientes y a las personas trabajadoras directrices o pautas documentadas de consumo energético responsable, como, por ejemplo:\nPautas para el ahorro energético para trabajadores:\n• Aprovechar la luz natural frente a la artificial.\n• Desconectar aparatos en stand-by.\n• Ajustar el termostato de cada estancia dentro de los niveles recomendados.\n• Programar el uso de energía en horarios valle.\n• Habilitar el uso de zonas comunes en función de la necesidad para evitar iluminar y aclimatar estancias sin uso.\nPautas para el ahorro energético para clientes:\n• Aprovechar la luz natural frente a la artificial.\n• Desconectar aparatos en stand-by.\n• Ajustar el termostato de estancias privadas dentro de los niveles recomendados.\nApagar los sistemas de calefacción y refrigeración cuando se abandone una estancia.",
